import java.util.*;
import java.io.*;
public class EdE {

	public static void main(String[] args) throws Exception{
		int num = 998244353;

		// TODO Auto-generated method stub
 		BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));
 		PrintWriter out = new PrintWriter(System.out);
 		StringTokenizer st = new StringTokenizer(bf.readLine());
 		long n = Long.parseLong(st.nextToken());
 		long k = Long.parseLong(st.nextToken());
 		long[] fact = new long[200001];
 		fact[0] = 1;
 		long ans1 = 1;
 		for(int i = 1;i<=200000;i++){
 			ans1= (ans1*i) % num;
 			fact[i] = ans1;
 		}
 		long ans = 0;
 		for (int i = 0;i<n-k;i++){
 			//ans+= (-1)^i*(n-k choose i)* (n-k-i)^n
 			long ks = 1;
			ks = ks * fact[(int)(n-k)]%num;
			ks = ks*power(fact[i], num-2, num)%num;
			ks = ks*power(fact[(int)(n-k-i)], num-2, num)%num;
 			if (i%2 == 0){

 				ans+= ks * power(n-k-i, n, num)%num;
 			}
 			else{
 				ans-= ks* power(n-k-i, n, num)%num;
 			}
 			ans = ans%num;
 		}
 		if (k >=n)
 			out.println(0);
 		else{
 		if (k != 0)
 			ans= ans*2%num;

 		ans = ans*fact[(int)(n)]%num;
 		ans = ans*power(fact[(int)(k)], num-2, num)%num;
 		ans = ans*power(fact[(int)(n-k)], num-2, num)%num;

 		while (ans < 0){
 			ans = ans+num;
 		}
 		out.println(ans);
 		}
 		out.close();

 	}


	public static int power(long x, long y, long mod){
		long ans = 1;
		while(y>0){
			if (y%2==1)
				ans = (ans*x)%mod;
			x = (x*x)%mod;
			y/=2;
		}
		return (int)(ans);
	}
 }

